"""C1: card-testing and impossible-travel rules, rule order.  C8: APPROVE always has a reason."""
import copy, time, unittest

from decision_service.config import DEFAULTS
from decision_service.engine import Model, decide_core, evaluate_rules

CFG = copy.deepcopy(DEFAULTS)


def feats(**kw):
    f = {"count_5m": 1, "amount_ratio": 1.0, "new_device": False, "country_changed": False, "tiny": False,
         "ecom": False, "cold": False, "blocked": False, "feature_age_s": 1.0, "stale": False}
    f.update(kw)
    return f


class C1Rules(unittest.TestCase):
    def test_card_testing_fires_on_third_tiny_ecom(self):
        self.assertEqual(evaluate_rules(feats(ecom=True, tiny=True, count_5m=3), CFG),
                         ("DECLINE", ["RULE_CARD_TESTING"]))
        self.assertEqual(evaluate_rules(feats(ecom=True, tiny=True, count_5m=2), CFG)[0], "APPROVE")
        self.assertEqual(evaluate_rules(feats(tiny=True, count_5m=3), CFG)[0], "APPROVE")   # in store: no

    def test_travel_needs_new_device(self):
        self.assertEqual(evaluate_rules(feats(country_changed=True, new_device=True), CFG),
                         ("STEP_UP", ["RULE_IMPOSSIBLE_TRAVEL"]))
        self.assertEqual(evaluate_rules(feats(country_changed=True), CFG)[0], "APPROVE")

    def test_order_strongest_first(self):
        self.assertEqual(evaluate_rules(feats(blocked=True, ecom=True, tiny=True, count_5m=3), CFG)[1],
                         ["RULE_BLOCKED"])
        self.assertEqual(evaluate_rules(feats(ecom=True, tiny=True, count_5m=3, country_changed=True,
                                              new_device=True), CFG)[1], ["RULE_CARD_TESTING"])


class C8ApproveReasons(unittest.TestCase):
    def setUp(self):
        self.now = time.time()
        self.txn = {"transaction_id": "t1", "event_time": "2026-11-05T09:00:00.000+00:00",
                    "amount_minor": 2000, "channel": "POS", "device_id": "dev_a",
                    "merchant": {"country": "US"}}
        self.item = {"known_devices": ["dev_a"], "avg_amount_30d": 20.0, "updated_at": self.now}

    def test_approve_with_model(self):
        res = decide_core(self.txn, self.item, [], CFG, Model(-5.0, {}), self.now)
        self.assertEqual((res["decision"], res["reasons"]), ("APPROVE", ["NO_RULE_HIT", "ML_LOW_RISK"]))

    def test_approve_without_model(self):
        res = decide_core(self.txn, self.item, [], CFG, None, self.now)
        self.assertEqual(res["reasons"], ["NO_RULE_HIT", "ML_UNAVAILABLE"])


if __name__ == "__main__":
    unittest.main()
